-- Catalog content of the current game buildings: descriptions, addresses, photos.
-- Photos: Wikimedia Commons (free licences, authors in docs/content-sources.md), re-encoded to WebP 1280px
-- and uploaded to the public Storage bucket 'building-photos' (migration 016) as <slug>.webp.
-- Replace YOUR-PROJECT with the Supabase project ref before running in the SQL Editor. Safe to re-run.

with base as (select 'https://YOUR-PROJECT.supabase.co/storage/v1/object/public/building-photos/' as url)
update public.buildings b set
  name = coalesce(c.name, b.name),
  address = c.address,
  description = c.description,
  image_url = case when c.photo is null then b.image_url else (select url from base) || c.photo || '.webp' end
from (values
  ('bolshoi-theatre', null, 'Театральная площадь, 1', 'bolshoi-theatre',
   'Главная сцена страны с квадригой Аполлона над портиком. Нынешнее здание построено по проекту Альберта Кавоса в 1856 году, после пожара, уничтожившего театр Осипа Бове. Бронзовую колесницу Аполлона создал скульптор Пётр Клодт. В 2005–2011 годах театр прошёл большую реставрацию: залу вернули историческое убранство и акустику.'),
  ('gum', null, 'Красная площадь, 3', 'gum',
   'Торговые ряды под стеклянной крышей. Здание построено в 1890–1893 годах по проекту Александра Померанцева, а лёгкие стеклянные своды над пассажами рассчитал инженер Владимир Шухов. В центре главного пассажа — фонтан, одно из самых популярных мест встреч в центре Москвы.'),
  ('historical-museum', null, 'Красная площадь, 1', 'historical-museum',
   'Красный терем в начале Красной площади. Здание в русском стиле построено по проекту Владимира Шервуда, музей открылся в 1883 году. Фасад украшают башенки и шатры в духе древнерусской архитектуры, а в собрании — предметы от каменного века до XX столетия.'),
  ('pashkov-house', null, 'улица Воздвиженка, 3/5', 'pashkov-house',
   'Белоснежный дворец на холме напротив Кремля. Усадьбу построили в 1784–1786 годах для Петра Пашкова; автором проекта принято считать Василия Баженова. Сегодня здание принадлежит Российской государственной библиотеке, а на его крыше Булгаков устроил прощание Воланда с Москвой.'),
  ('tsum', null, 'улица Петровка, 2', 'tsum',
   'Готический замок с витринами на Петровке. Универмаг построен в 1906–1908 годах по проекту Романа Клейна для торгового дома «Мюр и Мерилиз». Остроконечные башенки и стрельчатые окна сделали его одним из самых узнаваемых зданий центра.'),
  ('kievsky-station', null, 'площадь Киевского Вокзала, 1', 'kievsky-station',
   'Вокзал с часовой башней у Москвы-реки. Здание по проекту Ивана Рерберга строили в 1914–1918 годах, а стеклянный дебаркадер над платформами спроектировал Владимир Шухов. Отсюда уходят поезда на юго-запад и аэроэкспрессы во Внуково.'),
  ('hotel-ukraina', null, 'Кутузовский проспект, 2/1, стр. 1', 'hotel-ukraina',
   'Самая высокая гостиница среди сталинских высоток. Здание на Кутузовском проспекте построено в 1953–1957 годах по проекту Аркадия Мордвинова; вместе со шпилем оно поднимается более чем на 200 метров. Сейчас здесь отель Radisson Collection.'),
  ('msu-main', null, 'Ленинские горы, 1', 'msu-main',
   'Самая высокая из семи сталинских высоток — 240 метров со шпилем. Главное здание МГУ построено в 1949–1953 годах по проекту Льва Руднева и до 1990 года было самым высоким зданием Европы. Перед ним — аллея учёных и вид на Москву с Воробьёвых гор.'),
  ('ras-presidium', null, 'Ленинский проспект, 32А', 'ras-presidium',
   'Здание с «золотыми мозгами» на Ленинском проспекте. Комплекс Президиума Российской академии наук строился с 1970-х до начала 1990-х годов; крышу венчают позолоченные конструкции, которые москвичи прозвали «мозгами». Одно из самых заметных зданий позднесоветской архитектуры.'),
  ('gagarin-monument', null, 'площадь Гагарина', 'gagarin-monument',
   'Титановый Гагарин на взлёте. Монумент первому космонавту высотой 42,5 метра открыт в 1980 году, скульптор — Павел Бондаренко. Фигура сделана из титана — металла космической техники. Площадь обрамляют два полукруглых дома, похожих на парадные ворота в город.'),
  ('osm-w32611545', null, 'Варшавское шоссе, 69 к1', null,
   'Кирпичный дом начала 1960-х. Восьмиэтажный дом серии II-29 построен в 1961 году, в нём 140 квартир. На первом этаже — гастроном и салоны мебели и плитки.'),
  ('osm-w594736737', null, 'Варшавское шоссе, 69 к2', null,
   'Восьмиэтажный кирпичный дом 1961 года серии II-29, сосед корпуса 1. В доме 114 квартир.'),
  ('osm-w32611573', 'Театр «Шалом»', 'Варшавское шоссе, 71 к1', 'shalom',
   'Дом, в котором живёт театр. На первом этаже девятиэтажного кирпичного дома 1959 года работает Московский еврейский театр «Шалом», основанный в 1988 году. Его спектакли посвящены еврейской культуре, но обращены к зрителям любых национальностей.'),
  ('osm-w275901636', null, 'Варшавское шоссе, 71', null,
   'Нежилое здание в квартале у Варшавского шоссе.'),
  ('osm-w275901634', null, 'Варшавское шоссе, 71 к2', null,
   'Пятиэтажный жилой дом на Варшавском шоссе.'),
  ('osm-w275901633', null, 'Варшавское шоссе, 71 к3', null,
   'Трёхэтажное торговое здание. Здесь работает бар «Тихий».')
) as c(slug, name, address, photo, description)
where b.slug = c.slug;
